// Youku adapter — browser-first acquisition.
//
// Youku's mtop play API (mtop.youku.play.ups.appinfo.get/1.1) requires a
// signed request whose `sign` and `steal_params.ckey` are generated by the
// page's JS — pure-API replay is fragile. The working path (verified on
// ecs-node): load the show page in headless Chrome, intercept the ups
// response via CDP, extract data.stream[] m3u8 ladders.
//
// Caveat: VM IPs get rgv587 slider-punished even in real Chrome; the
// datacenter egress (ecs-node) passes cleanly.

import { captureResponse, evalInPage } from '../browser.js';

const UA =
  'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/131.0 Safari/537.36';

/** v.youku.com/v_show/id_<vid>.html | m.youku.com/video/id_<vid>.html | youku:vid:<vid> | youku:show:<encodeShowId> */
export function recognize(source) {
  const m =
    /v\.youku\.com\/v_show\/id_([A-Za-z0-9=]+)/i.exec(source) ||
    /m\.youku\.com\/(?:mid_)?video\/id_([A-Za-z0-9=]+)/i.exec(source) ||
    /^youku:(vid:[A-Za-z0-9=]+|show:[A-Za-z0-9=]+)$/i.exec(source);
  if (!m) return { matched: false };
  const raw = m[1];
  if (raw.startsWith('show:')) {
    return {
      matched: true,
      site_id: 'youku',
      locator: {
        site_id: 'youku',
        locator_version: 1,
        opaque_payload: { showId: raw.slice(5) },
      },
    };
  }
  const vid = raw.startsWith('vid:') ? raw.slice(4) : raw;
  return {
    matched: true,
    site_id: 'youku',
    locator: {
      site_id: 'youku',
      locator_version: 1,
      opaque_payload: { vid },
    },
  };
}

const SHOW = (vid) => `https://v.youku.com/v_show/id_${vid}.html`;

/** vid or showId → vid (via v_nextstage redirect). */
async function vidOf(locator) {
  if (locator.opaque_payload.vid) return locator.opaque_payload.vid;
  const r = await fetch(
    `https://v.youku.com/v_nextstage/id_${locator.opaque_payload.showId}.html`,
    { headers: { 'User-Agent': UA }, redirect: 'follow' },
  );
  const m = /id_([A-Za-z0-9=]+)\.html/.exec(r.url);
  if (!m) throw new Error('SHOW_RESOLVE_FAILED');
  return m[1];
}

const MOBILE_UA =
  'Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X) AppleWebKit/605.1.15 Mobile/15E148';
const MOBILE_SHOW = (vid) => `https://m.youku.com/video/id_${vid}.html`;

/**
 * Resolve a youku vid to m3u8 ladders. Two browser paths:
 *  1. m.youku.com/video/id_<vid>.html — mobile player calls
 *     ups.youku.com/ups/get.json with a self-generated ckey.
 *     Mobile pages are NOT rgv587-punished (verified 2026-09-23 while
 *     v.youku.com was fully captcha-blocked).
 *  2. v.youku.com fallback — PC player calls mtop ups.appinfo.get
 *     (blocked whenever the IP/device is flagged).
 * Both return data.stream[] with m3u8_url ladders.
 */
export async function resolve(locator, { prefer = {} } = {}) {
  const vid = await vidOf(locator);
  // Mobile path first — survives page punishment.
  let body = await captureResponse(
    MOBILE_SHOW(vid),
    /ups\.youku\.com\/ups\/get\.json/,
    40000,
    { ua: MOBILE_UA },
  );
  let d;
  if (body) {
    d = JSON.parse(body)?.data;
  } else {
    // PC fallback (mtop JSONP wrapper).
    body = await captureResponse(SHOW(vid), /ups\.appinfo\.get/, 25000);
    if (!body)
      throw Object.assign(new Error('BROWSER_BLOCKED'), { code: 'BROWSER_BLOCKED' });
    const json = JSON.parse(body.slice(body.indexOf('(') + 1, body.lastIndexOf(')')));
    d = json?.data?.data;
  }
  if (!d) throw Object.assign(new Error('UPSTREAM_ERROR'), { code: 'UPSTREAM_ERROR' });
  const err = d.error;
  if (err) {
    const code =
      err.code === -1002
        ? 'SOURCE_BLOCKED'
        : /vip|付费|会员/i.test(err.note || '')
          ? 'SOURCE_VIP'
          : 'SOURCE_UNSUPPORTED';
    throw Object.assign(new Error(`${code}: ${err.note || err.code}`), { code });
  }
  const streams = (d.stream || [])
    .filter((s) => s.m3u8_url)
    .sort((a, b) => (b.height || 0) - (a.height || 0))
    .map((s) => ({
      id: s.stream_type,
      kind: 'video',
      protocol: 'hls',
      url: s.m3u8_url,
      width: s.width,
      height: s.height,
      size: s.size,
      // Segment URLs are signed to the egress IP — they must be fetched
      // through the gateway's /seg proxy from the same node.
      upstream_headers: { 'User-Agent': UA },
    }));
  if (!streams.length)
    throw Object.assign(new Error('SOURCE_UNSUPPORTED'), { code: 'SOURCE_UNSUPPORTED' });
  // prefer.qn = target height; pick the highest ladder not exceeding it.
  const chosen = prefer.qn
    ? streams.find((s) => s.height <= prefer.qn) || streams[streams.length - 1]
    : streams[0];
  return {
    title: d.video?.title || vid,
    duration_ms: Math.round(Number(d.video?.seconds || 0) * 1000),
    is_preview: false,
    proxied_hls: true,
    quality: chosen.height,
    stream_idx: streams.indexOf(chosen),
    streams,
    quality_options: streams.map((s) => ({
      qn: s.height,
      label: `${s.height}p`,
    })),
  };
}

/**
 * Danmaku via the page's own mtop signer — mopen.youku.danmu.list is
 * called inside the loaded show page so lib.mtop.request produces a
 * valid sign.
 * Lazy by design: caller passes the mat (per-minute) buckets it needs
 * so call volume tracks playhead like the real player, not a
 * full-video crawl (mtop has anti-flood; bulk pulls get the egress IP
 * throttled).
 */
export const lazy_danmaku = true;

// --- pure-HTTP mtop signing ---
// _m_h5_tk cookie + md5(token&t&appKey&data) = sign. No browser needed
// for API calls — only the initial play-page resolve needs Chrome
// (steal_params.ckey lives in page JS, not mtop).

const MTOP_UA =
  'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/131.0 Safari/537.36';
const MTOP_APPKEY = '23774304';
let _mtopTk = null;
let _mtopTkEnc = null;

async function mtopTk() {
  if (_mtopTk) return;
  const r = await fetch(
    `https://acs.youku.com/h5/mtop.youku.danmu.common.profile/1.0/?jsv=2.6.1&appKey=${MTOP_APPKEY}&t=1&sign=x&api=x&v=1.0&type=originaljson&data=%7B%7D`,
    { headers: { 'User-Agent': MTOP_UA, Referer: 'https://v.youku.com/' } },
  );
  const cookies = r.headers.getSetCookie?.() || [];
  for (const c of cookies) {
    const m = c.match(/^(_m_h5_tk|_m_h5_tk_enc)=([^;]+)/);
    if (m) {
      if (m[1] === '_m_h5_tk') _mtopTk = m[2];
      else _mtopTkEnc = m[2];
    }
  }
}

async function mtop(api, v, data) {
  await mtopTk();
  const t = String(Date.now());
  const ds = JSON.stringify(data);
  const { createHash } = await import('node:crypto');
  const sign = createHash('md5')
    .update(`${_mtopTk.split('_')[0]}&${t}&${MTOP_APPKEY}&${ds}`)
    .digest('hex');
  const url =
    `https://acs.youku.com/h5/${api}/${v}/?jsv=2.6.1&appKey=${MTOP_APPKEY}` +
    `&t=${t}&sign=${sign}&api=${api}&v=${v}&type=originaljson&data=${encodeURIComponent(ds)}`;
  const r = await fetch(url, {
    headers: {
      'User-Agent': MTOP_UA,
      Referer: 'https://v.youku.com/',
      Cookie: `_m_h5_tk=${_mtopTk};_m_h5_tk_enc=${_mtopTkEnc}`,
    },
  });
  return r.json();
}

/**
 * Danmaku — pure HTTP via mtop signing. mat is a per-minute bucket;
 * lazy caller passes which buckets to fetch so call volume tracks
 * playhead like the real player.
 */
export async function danmaku(locator, { mats = [0, 1, 2] } = {}) {
  const vid = await vidOf(locator);
  const out = [];
  for (const mat of mats) {
    try {
      const d = await mtop('mopen.youku.danmu.list', '1.0', {
        pid: 0, ctype: 10004, vid, mat, mcount: 1, type: 1,
      });
      const inner = JSON.parse(d?.data?.result || '{}');
      const items = inner?.data?.result || [];
      for (const it of items) {
        const props =
          typeof it.propertis === 'string'
            ? JSON.parse(it.propertis)
            : it.propertis || {};
        const t = Number(it.playat || 0);
        const text = String(it.content || '').trim();
        if (Number.isFinite(t) && text)
          out.push({
            t,
            // pos: 3=scroll 4=top 0=default; map to bilibili mode
            mode: props.pos === 4 ? 5 : 1,
            color: Number(props.color) || 16777215,
            text,
          });
      }
      await new Promise((r) => setTimeout(r, 150 + Math.random() * 200));
    } catch {
      break;
    }
  }
  return out;
}

/**
 * Search — yksearch only exposes the hot-keyword board (default_page);
 * real keyword search requires so.youku.com which is rgv587-punished.
 * Returns hot-search items with encodeShowId (playable via v_nextstage).
 */
export async function search(keyword, { limit = 20 } = {}) {
  const d = await mtop('mtop.youku.soku.yksearch', '2.0', {
    keyword: keyword || '',
    pg: 1,
    pz: limit,
    appScene: 'default_page',
    appCaller: 'youku-search-sdk',
    searchFrom: 'search',
    sdkver: 314,
    pcKuFlixMode: 1,
  });
  const hits = [];
  const walk = (o) => {
    if (!o || typeof o !== 'object') return;
    const sid = o.encodeShowId || o.showId;
    const title = o.title || o.mainTitle || o.showTitle;
    if (sid && title)
      hits.push({
        vid: `show:${sid}`,
        title: String(title).replace(/<[^>]+>/g, ''),
        img: o.posterImage || o.img || o.poster || '',
        duration: o.duration || o.seconds || '',
        mark: `热搜${o.rank ? ' #' + o.rank : ''}`,
      });
    for (const v of Object.values(o)) walk(v);
  };
  walk(d?.data);
  return hits.slice(0, limit);
}
